-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (10133, 25, 'Beratung, Opferhilfe und Anlaufstellen für Betroffene von Hass und digitaler Gewalt ausbauen (Land)', 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'offen', null, 'land', null, true, 'blind'),
  (10134, 25, 'Schulung von Polizei, Justiz und Verwaltung zu Hasskriminalität und digitaler Gewalt (Land)', 'Sensibilisiertes Personal nimmt Anzeigen ernster und bearbeitet sie besser; die Wirkung ist aber mittelbar, Wirkungsstudien fehlen weitgehend. Landesbehörden können Schulungen selbst einführen.', 'offen', null, 'land', null, true, 'blind'),
  (10135, 25, 'Strafverfolgung von Hasskriminalität im Netz stärken: Personal, Spezialabteilungen, Spezialeinheiten (Land)', 'Spezialisierte Stellen und mehr Personal können Anzeigen schneller bearbeiten und Täter häufiger ermitteln. Gegen eine starke Einstufung: kaum Wirkungsstudien, Personalgewinnung dauert, Anonymität erschwert Ermittlungen.', 'offen', null, 'land', null, true, 'blind'),
  (10136, 25, 'Meldestellen und Monitoring für Hass und digitale Gewalt aufbauen und fördern (Land)', 'Niedrigschwellige Meldewege, auch unterhalb der Strafbarkeit, erleichtern Betroffenen das Melden und machen Vorfälle sichtbar. Wirkung auf spätere Verfolgung und Entfernung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (10137, 25, 'Hasskriminalität besser statistisch erfassen und berichten (Land)', 'Bessere Erfassung schafft eine Datengrundlage, verändert aber weder Meldeverhalten noch Verfolgung unmittelbar. Land kann Erfassung und Berichte selbst regeln.', 'offen', null, 'land', null, true, 'blind'),
  (10138, 25, 'Login-Falle und gerichtlich angeordnete Accountsperren zur Ermittlung anonymer Täter (Bund)', 'Kann anonyme Täter identifizierbar machen, an denen Ermittlungen bisher oft scheitern. Datenschutz- und EU-rechtliche Fragen sind zu klären; Erfahrungen mit dem Instrument liegen kaum vor.', 'offen', null, 'bund', null, true, 'blind'),
  (10139, 25, 'Digitales Gewaltschutzgesetz: Betroffenenrechte, Verbandsklage, leichtere Sperrung von Täter-Accounts (Bund)', 'Stärkt die Durchsetzung von Betroffenenrechten und Sperrungen gegenüber Plattformen und Tätern. Muss mit dem EU-Plattformrecht abgestimmt werden; Wirkung noch nicht belegt.', 'offen', null, 'bund', null, true, 'blind'),
  (10140, 25, 'Strafverfolgung von Online-Hasskriminalität stärken, BKA-Zentralstelle ausbauen (Bund)', 'Zentrale Stellen bündeln Meldungen und Fälle und können Verfahren beschleunigen; der Bund finanziert sie selbst. Wirkungsnachweise auf Hassaufkommen fehlen weitgehend.', 'offen', null, 'bund', null, true, 'blind'),
  (10141, 25, 'Strafrecht gegen Hetze und digitale sexualisierte Gewalt ergänzen oder verschärfen (Bund)', 'Schließt mögliche Strafbarkeitslücken, Forschung zeigt aber meist nur schwache Abschreckung durch höhere Strafen. Tatbestände zu Meinungsäußerungen sind verfassungsrechtlich heikel (Art. 5 GG).', 'gemischt', null, 'bund', null, true, 'blind'),
  (10142, 25, 'Bundesgesetze gegen digitale Gewalt und Deepfakes über den Bundesrat voranbringen (Land)', 'Die Rechtslage (StGB, Gewaltschutz) wäre wirksam zu ergänzen, liegt aber beim Bund. Das Land kann nur Initiativen im Bundesrat einbringen und hängt von Bundestag und Bundesregierung ab.', 'offen', null, 'land', null, true, 'blind'),
  (10143, 25, 'Plattformpflichten zur Entfernung rechtswidriger Inhalte und Aufsicht nach dem Digital Services Act (Bund)', 'Klare Pflichten und besser ausgestattete Aufsicht können die Entfernungsquote erhöhen. Der Rahmen ist EU-Recht, nationale Spielräume sind begrenzt; Wirkung bisheriger Regeln gemischt.', 'gemischt', null, 'bund', null, true, 'blind'),
  (10144, 25, 'Plattformen auf Schutz der Meinungsfreiheit verpflichten, Grenzen für Sorgfaltspflichten (Bund)', 'Zielt auf Begrenzung von Moderation und Löschung und bringt Schutz vor Hass und Bedrohung nicht voran. Zudem weitgehend durch EU-Recht (DSA) geregelt, nationale Alleingänge kaum möglich.', 'offen', null, 'bund', null, true, 'blind'),
  (10145, 25, 'Algorithmen von Plattformen stärker regulieren, offenlegen und prüfen (Bund)', 'Transparenz kann Verstärkung feindseliger Beiträge sichtbar machen; ein belegter Effekt auf Hass fehlt. Zuständig ist im Wesentlichen die EU (DSA), nationale Regeln sind kaum möglich.', 'offen', null, 'bund', null, true, 'blind'),
  (10146, 25, 'Öffentliche Förderung von Meldestellen beenden (Land)', 'Entzieht Meldewegen die Finanzierung und senkt tendenziell die Zahl gemeldeter Vorfälle, ohne andere Ursachen anzugehen. Als Haushaltsentscheidung des Landes leicht umsetzbar; Argument der Überlastung von Strafverfolgung ist nicht belegt.', 'offen', null, 'land', null, true, 'blind'),
  (10147, 25, 'Öffentliche Förderung von Meldestellen beenden, Meldestellen abschaffen (Bund)', 'Entzieht Meldewegen die Finanzierung und senkt tendenziell gemeldete Vorfälle. Förderende ist leicht möglich; eine Abschaffung der Stellen selbst stößt auf EU-Vorgaben (vertrauenswürdige Hinweisgeber) und Vereinsfreiheit.', 'offen', null, 'bund', null, true, 'blind'),
  (10148, 25, 'Sondertatbestand für Beleidigung von Politikern (§ 188 StGB) streichen oder nicht mehr aktiv verfolgen (Land)', 'Verringert den strafrechtlichen Schutz vor Anfeindungen und stärkt Betroffene nicht. Als Bundesrecht kann das Land nur über den Bundesrat darauf hinwirken.', 'offen', null, 'land', null, true, 'blind'),
  (10149, 25, 'Beleidigung von Personen des politischen Lebens (§ 188 StGB) streichen (Bund)', 'Verringert den strafrechtlichen Schutz vor Anfeindungen und stärkt Betroffene nicht; Beleidigung bleibt nach § 185 StGB strafbar. Gesetzesänderung durch den Bund rechtlich einfach möglich.', 'offen', null, 'bund', null, true, 'blind'),
  (10150, 25, 'Digitale Prävention, Aufklärung und Strategien gegen Hass im Netz (Digital Streetwork, Kampagnen, Jugendarbeit) (Land)', 'Aufklärung und Präventionsangebote können Hemmschwellen und Dynamiken in Debatten beeinflussen; Studien zu Gegenrede und Kampagnen zeigen uneinheitliche, oft kleine Effekte. Land kann sie selbst finanzieren.', 'gemischt', null, 'land', null, true, 'blind'),
  (10151, 25, 'Medienkompetenz in Schule und Erwachsenenbildung verankern und ausbauen (Land)', 'Verbessert den Umgang mit Inhalten und Desinformation; ein belegter Effekt auf Hass und Anfeindungen ist unsicher. Lehrplan und Lehrkräfte brauchen mehrere Jahre, Land ist zuständig.', 'gemischt', null, 'land', null, true, 'blind'),
  (10152, 25, 'Zivilgesellschaftliche Projekte und Initiativen gegen Hass dauerhaft fördern (Land)', 'Verlässliche Förderung sichert Beratung und Präventionsarbeit vor Ort; Bezug zu Hass im Netz ist oft indirekt, Wirkung kaum evaluiert. Landesmittel und Landesgesetz genügen.', 'offen', null, 'land', null, true, 'blind'),
  (10153, 25, 'Antidiskriminierungsstelle und zivilgesellschaftliche Opferberatung stärken und finanziell absichern (Bund)', 'Unterstützt Betroffene bei Beratung und Rechtsdurchsetzung, nicht speziell bei Hass im Netz. Dauerhafte Bundesförderung braucht Gesetz und Haushaltsmittel; Wirkung kaum evaluiert.', 'offen', null, 'bund', null, true, 'blind'),
  (10154, 25, 'Erfassung von Hasskriminalität verbessern, Straftaten gegen Betroffenengruppen einheitlich erfassen (Bund)', 'Schafft eine bessere Datenbasis und lenkt Verfolgung; Meldeverhalten und Plattformen ändert sie nicht direkt. Bund-Länder-Abstimmung der Statistik nötig.', 'offen', null, 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

