insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (10155, 25, 11, null, 'Umsetzung des Digital Services Act mit Schwerpunkt auf Transparenz, Kampf gegen Desinformation sowie Jugend- und Medienschutz', '{2502}', 10143, 2, 2, null, 'Klare Pflichten und besser ausgestattete Aufsicht können die Entfernungsquote erhöhen. Der Rahmen ist EU-Recht, nationale Spielräume sind begrenzt; Wirkung bisheriger Regeln gemischt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=41', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10156, 25, 11, null, 'Strafrecht gegen Volksverhetzung und antisemitische Äußerungen verschärfen', '{2501}', 10141, 1, 2, null, 'Schließt mögliche Strafbarkeitslücken, Forschung zeigt aber meist nur schwache Abschreckung durch höhere Strafen. Tatbestände zu Meinungsäußerungen sind verfassungsrechtlich heikel (Art. 5 GG).', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=46', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10157, 25, 11, 'BE', 'Beratungsangebote bei digitaler Gewalt ausbauen und die Strategien dagegen weiterentwickeln.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10158, 25, 11, 'BE', 'Neue Formen digitaler Gewalt wie digitale Belästigung und Mobbing in Sozialen Medien strafrechtlich bekämpfen; Gesetzeslücken schließen.', '{2501}', 10142, 2, 1, null, 'Die Rechtslage (StGB, Gewaltschutz) wäre wirksam zu ergänzen, liegt aber beim Bund. Das Land kann nur Initiativen im Bundesrat einbringen und hängt von Bundestag und Bundesregierung ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=12', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10159, 25, 11, 'BE', 'Spezialabteilung der Staatsanwaltschaft für Hasskriminalität ausbauen und stärken.', '{2501}', 10135, 2, 3, null, 'Spezialisierte Stellen und mehr Personal können Anzeigen schneller bearbeiten und Täter häufiger ermitteln. Gegen eine starke Einstufung: kaum Wirkungsstudien, Personalgewinnung dauert, Anonymität erschwert Ermittlungen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=22', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10160, 25, 11, 'BE', 'Bestehende Schutz-Anlaufstellen für Betroffene queerfeindlicher Straftaten fortführen.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=110', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10161, 25, 11, 'BE', 'Medienkompetenz als verbindlichen Bestandteil an allen Schulen verankern.', '{2503}', 10151, 1, 2, null, 'Verbessert den Umgang mit Inhalten und Desinformation; ein belegter Effekt auf Hass und Anfeindungen ist unsicher. Lehrplan und Lehrkräfte brauchen mehrere Jahre, Land ist zuständig.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=63', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10162, 25, 11, 'MV', 'Vorratsdatenspeicherung auf Bundesebene einfordern, um Hasskriminalität im Internet zu bekämpfen.', '{2501}', null, 1, 1, null, 'Speicherung kann Ermittlungen helfen; Studien zu Aufklärungsquoten sind uneinheitlich, und der EU-Rechtsrahmen (EuGH) setzt enge Grenzen. Das Land kann nur auf Bundesebene darauf hinwirken.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10163, 25, 11, 'MV', 'Strafrecht gegen digitale sexualisierte Gewalt mittels KI-Deepfakes weiterentwickeln.', '{2501}', 10142, 2, 1, null, 'Die Rechtslage (StGB, Gewaltschutz) wäre wirksam zu ergänzen, liegt aber beim Bund. Das Land kann nur Initiativen im Bundesrat einbringen und hängt von Bundestag und Bundesregierung ab.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=35', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10164, 25, 11, 'MV', 'Mindestalter von 14 Jahren für soziale Netzwerke, um Kinder besser vor Hassbotschaften zu schützen.', '{2503}', null, 1, 1, null, 'Weniger Kinder in sozialen Netzwerken sähen weniger Hass, Altersgrenzen lassen sich aber schwer durchsetzen. Die Regelung liegt bei Bund und EU (DSA, Jugendschutz), nicht beim Land.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=38', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10165, 25, 11, 'MV', 'Gesetzliche Klarnamen- und ID-Pflicht gegenüber Plattformbetreibern und Providern.', '{2503}', null, 1, 1, null, 'Könnte Enthemmung durch Anonymität verringern; Erfahrungen mit Klarnamenpflichten zeigen kaum weniger Hass. Zudem Bundes- und EU-Recht (Datenschutz, DSA), das Land kann sie nicht allein einführen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=38', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10166, 25, 11, 'ST', 'Medienkompetenz für alle Generationen mit Schulen, Landesmedienanstalt und Trägern ausbauen', '{2503}', 10151, 1, 2, null, 'Verbessert den Umgang mit Inhalten und Desinformation; ein belegter Effekt auf Hass und Anfeindungen ist unsicher. Lehrplan und Lehrkräfte brauchen mehrere Jahre, Land ist zuständig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=36', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10167, 25, 12, null, 'Digitales Gewaltschutzgesetz: Betroffene digitaler Gewalt sollen ihre Rechte durchsetzen können; Täter-Accounts sollen leichter gesperrt werden.', '{2501}', 10139, 2, 2, null, 'Stärkt die Durchsetzung von Betroffenenrechten und Sperrungen gegenüber Plattformen und Tätern. Muss mit dem EU-Plattformrecht abgestimmt werden; Wirkung noch nicht belegt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10168, 25, 12, null, 'Zentralstelle für strafbare Inhalte im Internet beim BKA ausbauen, um Online-Hasskriminalität effektiver zu verfolgen.', '{2501}', 10140, 2, 3, null, 'Zentrale Stellen bündeln Meldungen und Fälle und können Verfahren beschleunigen; der Bund finanziert sie selbst. Wirkungsnachweise auf Hassaufkommen fehlen weitgehend.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=48', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10169, 25, 12, null, 'Log-in-Falle: IP-Adressen bei verdächtigen Konten erfassen, um über Justiz-Schnittstellen Stammdaten zu ermitteln.', '{2501}', 10138, 2, 2, null, 'Kann anonyme Täter identifizierbar machen, an denen Ermittlungen bisher oft scheitern. Datenschutz- und EU-rechtliche Fragen sind zu klären; Erfahrungen mit dem Instrument liegen kaum vor.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10170, 25, 12, null, 'Plattformbetreiber verpflichten, illegale Inhalte zu entfernen.', '{2502}', 10143, 2, 2, null, 'Klare Pflichten und besser ausgestattete Aufsicht können die Entfernungsquote erhöhen. Der Rahmen ist EU-Recht, nationale Spielräume sind begrenzt; Wirkung bisheriger Regeln gemischt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10171, 25, 12, null, 'Plattformen verpflichten, ihre Algorithmen offenzulegen und auf diskriminierende oder manipulative Praktiken zu prüfen.', '{2503}', 10145, 1, 1, null, 'Transparenz kann Verstärkung feindseliger Beiträge sichtbar machen; ein belegter Effekt auf Hass fehlt. Zuständig ist im Wesentlichen die EU (DSA), nationale Regeln sind kaum möglich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=50', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10172, 25, 12, null, 'Antidiskriminierungsstelle stärken und Beratungsangebote für Betroffene ausbauen.', '{2501}', 10153, 1, 2, null, 'Unterstützt Betroffene bei Beratung und Rechtsdurchsetzung, nicht speziell bei Hass im Netz. Dauerhafte Bundesförderung braucht Gesetz und Haushaltsmittel; Wirkung kaum evaluiert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=41', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10173, 25, 12, null, 'Datenschutz für Betroffene von Hassdelikten: Wohnanschrift soll im Strafverfahren nicht mehr durch Akteneinsicht offengelegt werden müssen.', '{2501}', null, 2, 3, null, 'Nimmt Betroffenen die Sorge, dass Täter ihre Anschrift erfahren, und senkt so eine bekannte Hürde beim Anzeigen. Änderung der Strafprozessordnung ist Bundesrecht und ohne Mehrkosten möglich; Wirkung nicht untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=48', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10174, 25, 12, null, 'Strafrecht gegen Hetze überarbeiten: Schutzlücken bei menschenverachtender Hetze schließen, Volksverhetzungsparagrafen überarbeiten.', '{2501}', 10141, 1, 2, null, 'Schließt mögliche Strafbarkeitslücken, Forschung zeigt aber meist nur schwache Abschreckung durch höhere Strafen. Tatbestände zu Meinungsäußerungen sind verfassungsrechtlich heikel (Art. 5 GG).', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=48', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10175, 25, 12, 'BE', 'Medienkompetenz, kritischer Umgang mit sozialen Medien und digitale Verantwortung als fester Bestandteil schulischer Bildung, mit neuem Rahmenlehrplan Digitales.', '{2503}', 10151, 1, 2, null, 'Verbessert den Umgang mit Inhalten und Desinformation; ein belegter Effekt auf Hass und Anfeindungen ist unsicher. Lehrplan und Lehrkräfte brauchen mehrere Jahre, Land ist zuständig.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10176, 25, 12, 'BE', 'Digitale Präventionsansätze gegen Hassrede in eine Strategie für Demokratie und Zusammenhalt im Netz einbetten.', '{2503}', 10150, 1, 3, null, 'Aufklärung und Präventionsangebote können Hemmschwellen und Dynamiken in Debatten beeinflussen; Studien zu Gegenrede und Kampagnen zeigen uneinheitliche, oft kleine Effekte. Land kann sie selbst finanzieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=29', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10177, 25, 12, 'BE', 'Hasskriminalität online wie offline stärker verfolgen, Aufklärungsquoten erhöhen.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10178, 25, 12, 'BE', 'Spezialisierte Beratungsstellen für Betroffene von Hasskriminalität stärken.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=30', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10179, 25, 12, 'MV', 'Digitales Gewaltschutzgesetz mit Betroffenenrechten und Schließung von Strafverfolgungslücken im Bund', '{2501}', 10142, 2, 1, null, 'Die Rechtslage (StGB, Gewaltschutz) wäre wirksam zu ergänzen, liegt aber beim Bund. Das Land kann nur Initiativen im Bundesrat einbringen und hängt von Bundestag und Bundesregierung ab.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=38', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10180, 25, 12, 'MV', 'Kampagnen gegen Fake News und Fehlinformationen sowie Förderung von Medienkompetenz gegen Hass im Netz', '{2503}', 10150, 1, 3, null, 'Aufklärung und Präventionsangebote können Hemmschwellen und Dynamiken in Debatten beeinflussen; Studien zu Gegenrede und Kampagnen zeigen uneinheitliche, oft kleine Effekte. Land kann sie selbst finanzieren.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=44', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10181, 25, 12, 'ST', 'Fachkräfte im Umgang mit digitaler Gewalt schulen; digitale Präsenz von Strafverfolgungs- und Aufsichtsbehörden und digitale Beratungsangebote ausbauen', '{2501}', 10134, 1, 3, null, 'Sensibilisiertes Personal nimmt Anzeigen ernster und bearbeitet sie besser; die Wirkung ist aber mittelbar, Wirkungsstudien fehlen weitgehend. Landesbehörden können Schulungen selbst einführen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10182, 25, 12, 'ST', 'Digitale Gewalt, darunter Hass und Bedrohungen im Netz, soll konsequent verfolgt und bekämpft werden', '{2501}', 10135, 2, 3, null, 'Spezialisierte Stellen und mehr Personal können Anzeigen schneller bearbeiten und Täter häufiger ermitteln. Gegen eine starke Einstufung: kaum Wirkungsstudien, Personalgewinnung dauert, Anonymität erschwert Ermittlungen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10183, 25, 12, 'ST', 'Zivilgesellschaftliche Initiativen, die sich gegen Hass engagieren, verlässlich fördern', '{2503}', 10152, 1, 3, null, 'Verlässliche Förderung sichert Beratung und Präventionsarbeit vor Ort; Bezug zu Hass im Netz ist oft indirekt, Wirkung kaum evaluiert. Landesmittel und Landesgesetz genügen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10184, 25, 13, null, 'Strafbare Inhalte wie Beleidigung konsequent löschen und Accounts schneller sperren; digitales Gewaltschutzgesetz', '{2502,2501}', 10139, 2, 2, null, 'Stärkt die Durchsetzung von Betroffenenrechten und Sperrungen gegenüber Plattformen und Tätern. Muss mit dem EU-Plattformrecht abgestimmt werden; Wirkung noch nicht belegt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=114', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10185, 25, 13, null, 'Medienanstalten sollen mehr Ressourcen für Löschung und Verfolgung von Hasskriminalität im Netz erhalten', '{2502}', null, 2, 1, null, 'Mehr Mittel können Löschung und Verfolgung von Hass im Netz beschleunigen; Wirkung nicht untersucht. Medienanstalten sind Ländereinrichtungen, der Bund kann nur über Staatsvertrag und Länder beitragen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=115', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10186, 25, 13, null, 'Login-Falle und gerichtlich angeordnete Accountsperren, damit Strafverfolgung bei anonymen Accounts möglich wird', '{2501}', 10138, 2, 2, null, 'Kann anonyme Täter identifizierbar machen, an denen Ermittlungen bisher oft scheitern. Datenschutz- und EU-rechtliche Fragen sind zu klären; Erfahrungen mit dem Instrument liegen kaum vor.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=140', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10187, 25, 13, null, 'Verbreitung von KI-generierten oder echten Nacktbildern gegen den Willen der Betroffenen grundsätzlich strafbar machen', '{2501}', 10141, 1, 2, null, 'Schließt mögliche Strafbarkeitslücken, Forschung zeigt aber meist nur schwache Abschreckung durch höhere Strafen. Tatbestände zu Meinungsäußerungen sind verfassungsrechtlich heikel (Art. 5 GG).', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=119', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10188, 25, 13, null, 'Hasskriminalität gegen LSBTIQ* bekämpfen; Erfassung queerfeindlicher Straftaten verbessern; Unterstützungsangebote und Ansprechstellen ausbauen (Bezug zum Netz nicht genannt)', '{2501}', 10154, 1, 2, null, 'Schafft eine bessere Datenbasis und lenkt Verfolgung; Meldeverhalten und Plattformen ändert sie nicht direkt. Bund-Länder-Abstimmung der Statistik nötig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=121', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10189, 25, 13, null, 'Polizeistatistik reformieren, um Hasskriminalität besser zu erfassen', '{2501}', 10154, 1, 2, null, 'Schafft eine bessere Datenbasis und lenkt Verfolgung; Meldeverhalten und Plattformen ändert sie nicht direkt. Bund-Länder-Abstimmung der Statistik nötig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=133', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10190, 25, 13, null, 'Manipulative Algorithmen von Plattformen strenger regulieren; Algorithmen, die Kinder süchtig machen, nicht zulassen', '{2503}', 10145, 1, 1, null, 'Transparenz kann Verstärkung feindseliger Beiträge sichtbar machen; ein belegter Effekt auf Hass fehlt. Zuständig ist im Wesentlichen die EU (DSA), nationale Regeln sind kaum möglich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=85', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10191, 25, 13, null, 'Antisemitismusstrategie für den digitalen Raum erarbeiten', '{2503}', null, 1, 3, null, 'Eine Strategie bündelt Maßnahmen gegen Antisemitismus im Netz, ist aber selbst noch keine Maßnahme; Wirkung hängt von der Umsetzung ab. Bund kann sie allein erarbeiten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=116', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10192, 25, 13, 'BE', 'Zentrale Meldestelle für digitale Gewalt als Kompetenzzentrum, die Meldungen aufnimmt und die Zusammenarbeit mit Strafverfolgung koordiniert', '{2501}', 10136, 2, 3, null, 'Niedrigschwellige Meldewege, auch unterhalb der Strafbarkeit, erleichtern Betroffenen das Melden und machen Vorfälle sichtbar. Wirkung auf spätere Verfolgung und Entfernung ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=161', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10193, 25, 13, 'BE', 'Beratungs- und Unterstützungsangebote für Betroffene digitaler Gewalt ausbauen', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=133', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10194, 25, 13, 'BE', 'Digitale Präventionsangebote wie Digital Streetwork ausbauen und Medienkompetenz in allen Altersgruppen fördern', '{2503}', 10150, 1, 3, null, 'Aufklärung und Präventionsangebote können Hemmschwellen und Dynamiken in Debatten beeinflussen; Studien zu Gegenrede und Kampagnen zeigen uneinheitliche, oft kleine Effekte. Land kann sie selbst finanzieren.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=159', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10195, 25, 13, 'BE', 'Bekämpfung von Onlinekriminalität und Hasskriminalität im Netz stärken', '{2501}', 10135, 2, 3, null, 'Spezialisierte Stellen und mehr Personal können Anzeigen schneller bearbeiten und Täter häufiger ermitteln. Gegen eine starke Einstufung: kaum Wirkungsstudien, Personalgewinnung dauert, Anonymität erschwert Ermittlungen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=224', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10196, 25, 13, 'MV', 'Strafverfolgung von Bedrohungen im digitalen Raum stärken und Polizeien sowie Staatsanwaltschaften besser ausstatten.', '{2501}', 10135, 2, 3, null, 'Spezialisierte Stellen und mehr Personal können Anzeigen schneller bearbeiten und Täter häufiger ermitteln. Gegen eine starke Einstufung: kaum Wirkungsstudien, Personalgewinnung dauert, Anonymität erschwert Ermittlungen.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10197, 25, 13, 'MV', 'Beratungs- und Unterstützungsangebote für Opfer von Bedrohungen und Angriffen ausbauen.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://gruene-mv.de/?wpdmdl=33772#page=90', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10198, 25, 13, 'MV', 'Periodischen Sicherheitsbericht vorlegen, der gruppenbezogene Hasskriminalität sichtbar macht.', '{2501}', 10137, 1, 3, null, 'Bessere Erfassung schafft eine Datengrundlage, verändert aber weder Meldeverhalten noch Verfolgung unmittelbar. Land kann Erfassung und Berichte selbst regeln.', 'https://gruene-mv.de/?wpdmdl=33772#page=77', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10199, 25, 13, 'MV', 'Präventionskonzepte gegen sexualisierte und digitale Gewalt an Schulen, Hochschulen und am Arbeitsplatz.', '{2503}', 10150, 1, 3, null, 'Aufklärung und Präventionsangebote können Hemmschwellen und Dynamiken in Debatten beeinflussen; Studien zu Gegenrede und Kampagnen zeigen uneinheitliche, oft kleine Effekte. Land kann sie selbst finanzieren.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10200, 25, 13, 'MV', 'Demokratiebildung und Medienkompetenz in Lehrplänen und pädagogischer Ausbildung verankern, unter anderem zu Desinformation und digitaler Mündigkeit.', '{2503}', 10151, 1, 2, null, 'Verbessert den Umgang mit Inhalten und Desinformation; ein belegter Effekt auf Hass und Anfeindungen ist unsicher. Lehrplan und Lehrkräfte brauchen mehrere Jahre, Land ist zuständig.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10201, 25, 13, 'ST', 'Spezialisierte Anlaufstellen und niedrigschwellige Beratung für Betroffene ausbauen', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=46', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10202, 25, 13, 'ST', 'Staatsanwaltschaften und Gerichte bei Cyber- und Onlinekriminalität mit spezialisiertem Personal stärken', '{2501}', 10135, 2, 3, null, 'Spezialisierte Stellen und mehr Personal können Anzeigen schneller bearbeiten und Täter häufiger ermitteln. Gegen eine starke Einstufung: kaum Wirkungsstudien, Personalgewinnung dauert, Anonymität erschwert Ermittlungen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=46', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10203, 25, 13, 'ST', 'Unterrichtsfach Informatik und Medienbildung von Klasse 5 bis 10 verpflichtend einführen', '{2503}', 10151, 1, 2, null, 'Verbessert den Umgang mit Inhalten und Desinformation; ein belegter Effekt auf Hass und Anfeindungen ist unsicher. Lehrplan und Lehrkräfte brauchen mehrere Jahre, Land ist zuständig.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10204, 25, 13, 'ST', 'Landes-Demokratiefördergesetz für dauerhafte Förderung von Projekten gegen Extremismus und Hass', '{2503}', 10152, 1, 3, null, 'Verlässliche Förderung sichert Beratung und Präventionsarbeit vor Ort; Bezug zu Hass im Netz ist oft indirekt, Wirkung kaum evaluiert. Landesmittel und Landesgesetz genügen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=74', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10205, 25, 13, 'ST', 'Schutzkonzepte mit Sicherheitsberatung und Ansprechstellen für Engagierte, die von rechten Bedrohungen betroffen sind', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=75', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10206, 25, 14, null, 'Polizei soll LSBTI-feindliche Hasskriminalität bundesweit einheitlich erfassen und verfolgen.', '{2501}', 10154, 1, 2, null, 'Schafft eine bessere Datenbasis und lenkt Verfolgung; Meldeverhalten und Plattformen ändert sie nicht direkt. Bund-Länder-Abstimmung der Statistik nötig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=25', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10207, 25, 14, null, 'Sorgfaltspflichten für Plattformen aus dem Digital Services Act sollen die Meinungsfreiheit nicht beeinträchtigen und keine privaten Entscheidungen über die Grenzen der Meinungsfreiheit bringen.', '{2502}', 10144, 0, 1, null, 'Zielt auf Begrenzung von Moderation und Löschung und bringt Schutz vor Hass und Bedrohung nicht voran. Zudem weitgehend durch EU-Recht (DSA) geregelt, nationale Alleingänge kaum möglich.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=27', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10208, 25, 14, null, 'Lehrpläne mit mehr Raum für Medienkompetenz, neben wirtschaftlicher Bildung, MINT und Demokratie.', '{2503}', null, 1, 1, null, 'Mehr Raum für Medienkompetenz hilft beim Umgang mit Inhalten; Wirkung auf Hass ist unsicher. Lehrpläne sind Ländersache, der Bund kann nur über Vereinbarungen anregen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10209, 25, 14, 'BE', 'Aufklärung über psychische Gewalt im Internet stärken.', '{2503}', 10150, 1, 3, null, 'Aufklärung und Präventionsangebote können Hemmschwellen und Dynamiken in Debatten beeinflussen; Studien zu Gegenrede und Kampagnen zeigen uneinheitliche, oft kleine Effekte. Land kann sie selbst finanzieren.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10210, 25, 14, 'BE', 'Ehrdelikte bleiben Antragsdelikte; Hinweise von Polizei und Staatsanwaltschaft auf Ehrdelikte im Internet sollen eingestellt werden.', '{2501}', null, 0, 3, null, 'Das Einstellen polizeilicher Hinweise auf Ehrdelikte senkt Anzeigen, ändert aber nichts für Betroffene. Der Erhalt des Antragsdelikts schützt Selbstbestimmung. Praxis der Landesbehörden ist leicht änderbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=76', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10211, 25, 14, 'BE', 'Opfer von Gewalt sollen sofort psychologische Betreuung erhalten; Schutz vor Stalking und Hasskriminalität durch höhere Strafandrohung.', '{2501}', null, 1, 2, null, 'Psychologische Soforthilfe stützt Betroffene, die höhere Strafandrohung (Bundesrecht) schreckt kaum ab. Nicht auf das Netz bezogen; Betreuung ist Landessache, Strafrahmen nur über den Bund änderbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=73', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10212, 25, 14, 'BE', 'Schulungen von Polizei, Staatsanwaltschaft und Gerichten zu antisemitischen Aussagen und Straftaten.', '{2501}', 10134, 1, 3, null, 'Sensibilisiertes Personal nimmt Anzeigen ernster und bearbeitet sie besser; die Wirkung ist aber mittelbar, Wirkungsstudien fehlen weitgehend. Landesbehörden können Schulungen selbst einführen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=78', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10213, 25, 14, 'BE', 'Monitoringstellen und Vereine gegen Antisemitismus weiter fördern, auch für Vorfälle unter der Strafbarkeitsgrenze.', '{2501}', 10136, 2, 3, null, 'Niedrigschwellige Meldewege, auch unterhalb der Strafbarkeit, erleichtern Betroffenen das Melden und machen Vorfälle sichtbar. Wirkung auf spätere Verfolgung und Entfernung ist kaum untersucht.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=79', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10214, 25, 14, 'BE', 'Schulungen von Polizei, Justiz und Verwaltung zu queerfeindlicher Gewalt und Hasskriminalität.', '{2501}', 10134, 1, 3, null, 'Sensibilisiertes Personal nimmt Anzeigen ernster und bearbeitet sie besser; die Wirkung ist aber mittelbar, Wirkungsstudien fehlen weitgehend. Landesbehörden können Schulungen selbst einführen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=82', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10215, 25, 14, 'MV', 'Paragraf 188 StGB (Schutz von Personen des politischen Lebens vor Verleumdung) ersatzlos streichen; dafür auf Bundesebene eintreten.', '{2501}', 10148, 0, 1, null, 'Verringert den strafrechtlichen Schutz vor Anfeindungen und stärkt Betroffene nicht. Als Bundesrecht kann das Land nur über den Bundesrat darauf hinwirken.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=151', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10216, 25, 14, 'ST', 'Digitale Bildung und Medienkompetenz in Schule und Lehrkräftebildung verankern (Informationen prüfen, Desinformation erkennen, verantwortungsvoll kommunizieren).', '{2503}', 10151, 1, 2, null, 'Verbessert den Umgang mit Inhalten und Desinformation; ein belegter Effekt auf Hass und Anfeindungen ist unsicher. Lehrplan und Lehrkräfte brauchen mehrere Jahre, Land ist zuständig.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=25', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10217, 25, 15, null, 'NetzDG rückabwickeln und die Umsetzung des EU-Digital-Services-Act in Deutschland ablehnen.', '{2502}', null, 0, 0, null, 'Würde Plattformpflichten zur Entfernung rechtswidriger Inhalte abschaffen und Meldewege schwächen. Der Digital Services Act gilt als EU-Verordnung unmittelbar; seine Ablehnung ist EU-rechtswidrig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=50', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10218, 25, 15, null, 'Große Anbieter sozialer Medien sollen verpflichtet werden, die Meinungsfreiheit ihrer Nutzer zu respektieren.', '{2502}', 10144, 0, 1, null, 'Zielt auf Begrenzung von Moderation und Löschung und bringt Schutz vor Hass und Bedrohung nicht voran. Zudem weitgehend durch EU-Recht (DSA) geregelt, nationale Alleingänge kaum möglich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=132', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10219, 25, 15, null, 'Antisemitische Beleidigungen und Angriffe auf Juden sollen konsequent strafrechtlich geahndet werden.', '{2501}', 10140, 2, 3, null, 'Zentrale Stellen bündeln Meldungen und Fälle und können Verfahren beschleunigen; der Bund finanziert sie selbst. Wirkungsnachweise auf Hassaufkommen fehlen weitgehend.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=124', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10220, 25, 15, 'BE', 'Öffentliche Förderung von Meldestellen beenden, sodass sie sich ausschließlich privat finanzieren', '{2501}', 10146, 0, 3, null, 'Entzieht Meldewegen die Finanzierung und senkt tendenziell die Zahl gemeldeter Vorfälle, ohne andere Ursachen anzugehen. Als Haushaltsentscheidung des Landes leicht umsetzbar; Argument der Überlastung von Strafverfolgung ist nicht belegt.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=77', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10221, 25, 15, 'MV', 'Das Sonderrecht für Politikerbeleidigungen abschaffen; Staatsanwaltschaften und Gerichte sollen das Strafrecht konsequent anwenden.', '{2501}', 10148, 0, 1, null, 'Verringert den strafrechtlichen Schutz vor Anfeindungen und stärkt Betroffene nicht. Als Bundesrecht kann das Land nur über den Bundesrat darauf hinwirken.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=43', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10222, 25, 15, 'ST', 'Gesetzesänderungen gegen Hasskriminalität aus dem Jahr 2021 im Strafgesetzbuch wieder rückgängig machen', '{2501}', null, 0, 1, null, 'Würde Strafbarkeits- und Melderegeln gegen Hass im Netz zurücknehmen und Betroffenen nicht helfen. Die Gesetze sind Bundesrecht, das Land kann nur im Bundesrat darauf hinwirken.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=223', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10223, 25, 16, null, 'EU-Plattformrecht (Digital Services Act) zügig ins nationale Recht überführen und weiterentwickeln', '{2502}', 10143, 2, 2, null, 'Klare Pflichten und besser ausgestattete Aufsicht können die Entfernungsquote erhöhen. Der Rahmen ist EU-Recht, nationale Spielräume sind begrenzt; Wirkung bisheriger Regeln gemischt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=57', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10224, 25, 16, null, 'Bundesnetzagentur mit ausreichend Personal ausstatten, um Verbraucherschutz und den Digital Services Act umzusetzen', '{2502}', 10143, 2, 2, null, 'Klare Pflichten und besser ausgestattete Aufsicht können die Entfernungsquote erhöhen. Der Rahmen ist EU-Recht, nationale Spielräume sind begrenzt; Wirkung bisheriger Regeln gemischt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=57', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10225, 25, 16, null, 'Opferberatungen und Projekte gegen Rechtsextremismus stärker unterstützen und langfristig finanziell absichern', '{2501}', 10153, 1, 2, null, 'Unterstützt Betroffene bei Beratung und Rechtsdurchsetzung, nicht speziell bei Hass im Netz. Dauerhafte Bundesförderung braucht Gesetz und Haushaltsmittel; Wirkung kaum evaluiert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=51', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10226, 25, 16, null, 'Straftaten gegen Medienschaffende gesondert erfassen und von spezialisierten Staatsanwaltschaften bearbeiten lassen', '{2501}', 10154, 1, 2, null, 'Schafft eine bessere Datenbasis und lenkt Verfolgung; Meldeverhalten und Plattformen ändert sie nicht direkt. Bund-Länder-Abstimmung der Statistik nötig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=55', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10227, 25, 16, null, 'Plattformen bei Falschinformationen und Rechtsverstößen durch KI-erzeugte Inhalte haftbar machen', '{2502}', null, 1, 1, null, 'Haftung für KI-Inhalte könnte Moderationsanreize erhöhen, trifft aber vor allem Falschinformation. Die Plattformhaftung ist im DSA geregelt, ein nationaler Alleingang ist nicht möglich.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=55', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10228, 25, 16, 'BE', 'Technik-Kompetenzzentren für Beratung, Weiterbildung und Forensik bei digitaler Gewalt aufbauen.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=287', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10229, 25, 16, 'BE', 'Fortbildungsoffensive und Spezialeinheiten in Polizei und Justiz gegen digitale Gewalt.', '{2501}', 10135, 2, 3, null, 'Spezialisierte Stellen und mehr Personal können Anzeigen schneller bearbeiten und Täter häufiger ermitteln. Gegen eine starke Einstufung: kaum Wirkungsstudien, Personalgewinnung dauert, Anonymität erschwert Ermittlungen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=287', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10230, 25, 16, 'BE', 'Gesetzliche Regelungen gegen nicht einvernehmliche sexualisierte KI-Deepfakes fordern.', '{2501}', 10142, 2, 1, null, 'Die Rechtslage (StGB, Gewaltschutz) wäre wirksam zu ergänzen, liegt aber beim Bund. Das Land kann nur Initiativen im Bundesrat einbringen und hängt von Bundestag und Bundesregierung ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=287', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10231, 25, 16, 'BE', 'Medienkompetenzzentren in allen Bezirken, kostenfreie Angebote und Schulungen für Fachkräfte.', '{2503}', 10151, 1, 2, null, 'Verbessert den Umgang mit Inhalten und Desinformation; ein belegter Effekt auf Hass und Anfeindungen ist unsicher. Lehrplan und Lehrkräfte brauchen mehrere Jahre, Land ist zuständig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=178', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10232, 25, 16, 'BE', 'Ressortübergreifende Strategie gegen antimuslimischen Rassismus, die auch für den digitalen Raum gilt.', '{2503}', 10150, 1, 3, null, 'Aufklärung und Präventionsangebote können Hemmschwellen und Dynamiken in Debatten beeinflussen; Studien zu Gegenrede und Kampagnen zeigen uneinheitliche, oft kleine Effekte. Land kann sie selbst finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=272', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10233, 25, 16, 'BE', 'Jugendarbeit stärker auf digitale Gewaltprävention und Empowerment ausrichten.', '{2503}', 10150, 1, 3, null, 'Aufklärung und Präventionsangebote können Hemmschwellen und Dynamiken in Debatten beeinflussen; Studien zu Gegenrede und Kampagnen zeigen uneinheitliche, oft kleine Effekte. Land kann sie selbst finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=276', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10234, 25, 16, 'BE', 'Unabhängige Meldestellen für queerfeindliche Gewalt ausbauen und Opferberatung stärken.', '{2501}', 10136, 2, 3, null, 'Niedrigschwellige Meldewege, auch unterhalb der Strafbarkeit, erleichtern Betroffenen das Melden und machen Vorfälle sichtbar. Wirkung auf spätere Verfolgung und Entfernung ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=218', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10235, 25, 16, 'BE', 'Betroffene von Hassgewalt besser unterstützen und den Hilfsfonds ausbauen.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=289', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10236, 25, 16, 'BE', 'Angriffe auf Obdachlose künftig als Hasskriminalität erfassen.', '{2501}', 10137, 1, 3, null, 'Bessere Erfassung schafft eine Datengrundlage, verändert aber weder Meldeverhalten noch Verfolgung unmittelbar. Land kann Erfassung und Berichte selbst regeln.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=289', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10237, 25, 16, 'BE', 'Projekte gegen Antisemitismus stärken, die Vorfälle monitoren und Opfer beraten.', '{2501}', 10136, 2, 3, null, 'Niedrigschwellige Meldewege, auch unterhalb der Strafbarkeit, erleichtern Betroffenen das Melden und machen Vorfälle sichtbar. Wirkung auf spätere Verfolgung und Entfernung ist kaum untersucht.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=271', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10238, 25, 16, 'BE', 'Beratung, Opferhilfe und anonyme Beschwerdestellen bei extrem rechten Vorfällen stärken.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=326', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10239, 25, 16, 'MV', 'Beratungs- und Unterstützungsangebote für Betroffene digitaler Gewalt ausbauen', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10240, 25, 16, 'MV', 'Hasskriminalität konsequent bekämpfen und Prävention mit Opferschutz verzahnen', '{2501}', 10135, 2, 3, null, 'Spezialisierte Stellen und mehr Personal können Anzeigen schneller bearbeiten und Täter häufiger ermitteln. Gegen eine starke Einstufung: kaum Wirkungsstudien, Personalgewinnung dauert, Anonymität erschwert Ermittlungen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=7', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10241, 25, 16, 'MV', 'Polizei und Justiz für digitale Gewalt sensibilisieren und fortbilden', '{2501}', 10134, 1, 3, null, 'Sensibilisiertes Personal nimmt Anzeigen ernster und bearbeitet sie besser; die Wirkung ist aber mittelbar, Wirkungsstudien fehlen weitgehend. Landesbehörden können Schulungen selbst einführen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10242, 25, 16, 'MV', 'Medienbildung auf allen Ebenen ausbauen, auch Lehrkräfte- und Erwachsenenbildung', '{2503}', 10151, 1, 2, null, 'Verbessert den Umgang mit Inhalten und Desinformation; ein belegter Effekt auf Hass und Anfeindungen ist unsicher. Lehrplan und Lehrkräfte brauchen mehrere Jahre, Land ist zuständig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10243, 25, 16, 'MV', 'Projekte unterstützen, die sich gegen Hass und digitale Übergriffe engagieren', '{2503}', 10152, 1, 3, null, 'Verlässliche Förderung sichert Beratung und Präventionsarbeit vor Ort; Bezug zu Hass im Netz ist oft indirekt, Wirkung kaum evaluiert. Landesmittel und Landesgesetz genügen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=14', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10244, 25, 16, 'MV', 'Bundesebene: Haftungs- und Sorgfaltspflichten für Tech-Konzerne, transparente Algorithmen', '{2503}', null, 1, 1, null, 'Haftungs- und Sorgfaltspflichten sowie Algorithmentransparenz könnten Schutz vor Hass stärken; Wirkung unbelegt, vor allem Jugendschutz. Das Land kann nur auf Bundesebene darauf hinwirken; Regeln liegen bei der EU.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=27', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10245, 25, 16, 'ST', 'Beratungsstellen gegen Hass im Netz stärken.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=21', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10246, 25, 16, 'ST', 'Spezialisierte Ansprechpartner:innen bei jeder Polizeibehörde und jedem Landkreis gegen Hasskriminalität.', '{2501}', 10133, 2, 3, null, 'Beratung und Anlaufstellen senken Hürden, Vorfälle zu melden und anzuzeigen. Gegen eine starke Einstufung spricht, dass Wirkungsstudien zu diesen Angeboten kaum vorliegen; Land kann es allein finanzieren.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=127', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10247, 25, 17, null, 'Staatlich geförderte Meldestellen für Meinungsäußerungen abschaffen und nicht mehr aus Steuergeld finanzieren', '{2501}', 10147, 0, 2, null, 'Entzieht Meldewegen die Finanzierung und senkt tendenziell gemeldete Vorfälle. Förderende ist leicht möglich; eine Abschaffung der Stellen selbst stößt auf EU-Vorgaben (vertrauenswürdige Hinweisgeber) und Vereinsfreiheit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=39', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10248, 25, 17, null, 'Polizei von Hausdurchsuchungen wegen Politikerbeleidigung und der Suche im Internet nach Beleidigungen entlasten', '{2501}', null, 0, 3, null, 'Verringert die Verfolgung von Beleidigungen und hilft Betroffenen nicht. Polizeiliche Prioritäten lassen sich rechtlich leicht ändern; für eine Entlastung der Polizei sprechen knappe Ressourcen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10249, 25, 17, null, 'Beleidigung von Personen des politischen Lebens aus dem Strafgesetzbuch (§ 188) streichen', '{2501}', 10149, 0, 3, null, 'Verringert den strafrechtlichen Schutz vor Anfeindungen und stärkt Betroffene nicht; Beleidigung bleibt nach § 185 StGB strafbar. Gesetzesänderung durch den Bund rechtlich einfach möglich.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=35', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10250, 25, 17, 'BE', 'Abschaffung von Meldeportalen für strafrechtlich nicht relevante Meinungsäußerungen.', '{2501}', 10146, 0, 3, null, 'Entzieht Meldewegen die Finanzierung und senkt tendenziell die Zahl gemeldeter Vorfälle, ohne andere Ursachen anzugehen. Als Haushaltsentscheidung des Landes leicht umsetzbar; Argument der Überlastung von Strafverfolgung ist nicht belegt.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=31', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10251, 25, 17, 'MV', 'Politische Bildung und eine offene Debattenkultur an Regionalschulen stärken, mit Respekt und Meinungsvielfalt', '{2503}', 10150, 1, 3, null, 'Aufklärung und Präventionsangebote können Hemmschwellen und Dynamiken in Debatten beeinflussen; Studien zu Gegenrede und Kampagnen zeigen uneinheitliche, oft kleine Effekte. Land kann sie selbst finanzieren.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=49', null, 'gemischt', '2026-10-14', false, true, 'blind');

